param([string]$RepoRoot=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path,[string]$RunId='aot_flow_full_v31_pipeline',[string]$OutputRoot='')
if(-not $OutputRoot){$OutputRoot=Join-Path $RepoRoot 'artifacts\route_b_official\aot_action_bank_flow_full_v31_pipeline'};$pidFile=Join-Path $OutputRoot "${RunId}_pid.txt";$metaFile=Join-Path $OutputRoot "${RunId}_meta.txt";$pidValue=if(Test-Path -LiteralPath $pidFile){Get-Content -LiteralPath $pidFile|Select-Object -First 1}else{''};$process=if($pidValue-match'^\d+$'){Get-CimInstance Win32_Process -Filter "ProcessId = $pidValue" -ErrorAction SilentlyContinue}else{$null};$native=if($pidValue-match'^\d+$'){Get-Process -Id $pidValue -ErrorAction SilentlyContinue}else{$null};if($process-and$process.CommandLine-like'*aot_flow_full_v31_pipeline.py*'){Write-Host "RUNNING=true PID=$pidValue";if($native){Write-Host "PID_START=$($native.StartTime.ToString('yyyy-MM-dd HH:mm:ss'))"};Write-Host "PROCESS_COMMAND=$($process.CommandLine)"}else{Write-Host "NOT RUNNING PID=$pidValue"};$meta=@{};if(Test-Path -LiteralPath $metaFile){foreach($line in Get-Content -LiteralPath $metaFile){$pair=$line.Split('=',2);if($pair.Count-eq2){$meta[$pair[0]]=$pair[1]}}};$progress=$meta['progress'];if($progress-and(Test-Path -LiteralPath $progress)){$value=Get-Content -LiteralPath $progress -Raw|ConvertFrom-Json;Write-Host "done/total: $($value.done)/$($value.total)";Write-Host "last output timestamp: $((Get-Item -LiteralPath $progress).LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss'))";Write-Host "last completed unit: $($value.phase)";if($value.result){Write-Host ($value.result|ConvertTo-Json -Compress)}}else{Write-Host 'done/total: 0/3';Write-Host 'last output timestamp: none';Write-Host 'last completed unit: none'};Write-Host "stdout log: $($meta['stdout'])";Write-Host "stderr log: $($meta['stderr'])";if($meta['stderr']-and(Test-Path -LiteralPath $meta['stderr'])){Get-Content -LiteralPath $meta['stderr'] -Tail 10}

